import{_ as a,o as l,c as o,a2 as i}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"1.2 特种作业人员管理制度","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-2-te-zhong-zuo-ye-ren-yuan-guan-li-zhi-du.md","filePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-2-te-zhong-zuo-ye-ren-yuan-guan-li-zhi-du.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-2-te-zhong-zuo-ye-ren-yuan-guan-li-zhi-du.md"};function n(e,t,s,g,h,d){return l(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="_1-2-特种作业人员管理制度" tabindex="-1">1.2 特种作业人员管理制度 <a class="header-anchor" href="#_1-2-特种作业人员管理制度" aria-label="Permalink to &quot;1.2 特种作业人员管理制度&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;特种作业&quot;是电工证的本源。为什么电工要考证、证的有效期多长、多久复审一次、报考要过哪些关——这些制度性知识是机考的固定出题点,而且都是<strong>数字题、记忆题</strong>,记住了就拿分。</p><h2 id="一、什么是特种作业" tabindex="-1">一、什么是特种作业 <a class="header-anchor" href="#一、什么是特种作业" aria-label="Permalink to &quot;一、什么是特种作业&quot;">​</a></h2><p><strong>特种作业</strong>,指容易发生人员伤亡事故,对操作者本人、他人及周围设施的安全有重大危险的作业。国家规定这类作业的人员必须经过专门培训、考核合格,取得资格证书后才能上岗。</p><p>常见特种作业目录(部分):</p><ul><li>✅ <strong>电工类</strong>:低压电工作业、高压电工作业、电力电缆作业、继电保护作业、电气试验作业、防爆电气作业</li><li>焊接与热切割作业(焊工)</li><li>高处作业(架子工、登高作业)</li><li>制冷与空调作业</li><li>危险化学品安全作业 等</li></ul><blockquote><p>💡 我们考的<strong>低压电工作业</strong>,就是特种作业目录中的电工类之一,对应的证书叫《特种作业操作证(低压电工作业)》。</p></blockquote><h2 id="二、考证流程-五步拿证" tabindex="-1">二、考证流程:五步拿证 <a class="header-anchor" href="#二、考证流程-五步拿证" aria-label="Permalink to &quot;二、考证流程:五步拿证&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报名培训 → 完成学时 → 理论机考 → 实操考核 → 考核合格发证</span></span></code></pre></div><ol><li><strong>报名培训</strong>:到有资质的培训机构报名(应急管理部门认可的安全培训机构),提交身份证明等材料。</li><li><strong>完成学时</strong>:按要求完成安全技术培训学时(理论和实操都要培训)。</li><li><strong>理论机考</strong>:计算机考试,考安全生产知识与电工专业知识,满分 100 分,<strong>80 分及格</strong>。</li><li><strong>实操考核</strong>:现场考核仪表使用、线路接线、安全操作、急救等技能。</li><li><strong>发证</strong>:两科合格后,由应急管理部门颁发《特种作业操作证》。</li></ol><h2 id="三、报考条件-记数字" tabindex="-1">三、报考条件(记数字) <a class="header-anchor" href="#三、报考条件-记数字" aria-label="Permalink to &quot;三、报考条件(记数字)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>要求</th></tr></thead><tbody><tr><td>年龄</td><td>年满 <strong>18 周岁</strong>,不超过国家法定退休年龄</td></tr><tr><td>文化程度</td><td>初中及以上文化程度</td></tr><tr><td>身体条件</td><td>身体健康,无妨碍从事低压电工工作的疾病和生理缺陷(如色盲、癫痫等)</td></tr><tr><td>安全技术</td><td>具备必要的安全技术知识与技能</td></tr></tbody></table><h2 id="四、证书管理与复审-重点" tabindex="-1">四、证书管理与复审(重点!) <a class="header-anchor" href="#四、证书管理与复审-重点" aria-label="Permalink to &quot;四、证书管理与复审(重点!)&quot;">​</a></h2><p>特种作业操作证是 <strong>IC 卡式</strong>,全国通用,样式类似一张信用卡,上面有照片、姓名、作业类别、有效期等信息。</p><ul><li><strong>有效期:6 年</strong>。到期需要换发新证。</li><li><strong>复审周期:每 3 年复审一次</strong>。复审由持证人到原考核发证机关或其委托的机构办理。</li><li>证书在<strong>全国范围内有效</strong>,跨省也能用。</li><li>证书是<strong>上岗凭证</strong>:作业时必须随身携带或能出示;<strong>不得转借、转让、涂改、伪造</strong>。</li><li>证书真伪可在<strong>应急管理部官网</strong>查询(输入身份证号/证书编号)。</li></ul><blockquote><p>⚠️ 高频考点:&quot;6 年有效期、3 年复审&quot;这两个数字几乎是逢考必出,务必记牢。</p></blockquote><h2 id="五、为什么必须持证上岗" tabindex="-1">五、为什么必须持证上岗 <a class="header-anchor" href="#五、为什么必须持证上岗" aria-label="Permalink to &quot;五、为什么必须持证上岗&quot;">​</a></h2><p>《安全生产法》规定:生产经营单位的特种作业人员<strong>必须按照国家有关规定经专门的安全作业培训,取得相应资格,方可上岗作业</strong>。</p><p>无证上岗的后果:</p><ul><li>属于违法行为,用人单位要承担法律责任(可能被责令改正、罚款、停产停业整顿);</li><li>一旦发生事故,无证作业人员的责任更大;</li><li>出了事故保险理赔也可能受影响。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 低压电工操作证有效期 <strong>6 年</strong>,每 <strong>3 年</strong>复审一次。</li><li>✅ 报考年龄要求:年满 <strong>18 周岁</strong>。</li><li>✅ 理论机考合格线:<strong>80 分</strong>(满分 100 分)。</li><li>✅ 证书<strong>全国通用</strong>,<strong>禁止转借转让</strong>。</li><li>⚠️ 易混点:复审周期(3 年)和有效期(6 年)是两个不同概念,别搞混。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>低压电工属于<strong>特种作业</strong>,证书由<strong>应急管理部门</strong>考核发证。</li><li>考证五步:报名 → 培训 → 理论机考(80 分及格)→ 实操考核 → 发证。</li><li>证书 <strong>6 年有效、3 年复审、全国通用、禁止转借</strong>。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(单选)特种作业操作证的有效期是()。 A. 2 年　B. 3 年　C. 6 年　D. 4 年</li><li>(单选)特种作业操作证每()年复审一次。 A. 1　B. 2　C. 3　D. 5</li><li>(判断)低压电工作业操作证可以转借给同事使用。( )</li><li>(单选)报考低压电工特种作业操作证,年龄要求是()。 A. 年满 16 周岁　B. 年满 18 周岁　C. 年满 20 周岁　D. 年满 22 周岁</li><li>(单选)理论机考满分 100 分,及格线是()。 A. 60 分　B. 70 分　C. 80 分　D. 90 分</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>C</strong>。有效期 6 年。</li><li><strong>C</strong>。每 3 年复审一次。</li><li><strong>×</strong>。特种作业操作证禁止转借、转让、涂改、伪造,必须本人持证上岗。</li><li><strong>B</strong>。年满 18 周岁,且不超过国家法定退休年龄。</li><li><strong>C</strong>。理论机考 80 分及格。</li></ol></details>',28)])])}const p=a(r,[["render",n]]);export{c as __pageData,p as default};
